  "avaliacoes": [
    {
      "id": "E5b0085ef8c7f4911",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Na orientação de inspeção para FPSO monohull, cargas derrubadas sobre o convés de processo aparecem entre os principais perigos potenciais de perda de contenção.",
          "trechos": [
            "E5b0085ef8c7f4911:0:699",
            "E5b0085ef8c7f4911:699:1397"
          ],
          "condicoes": [
            "Aplicável ao escopo da orientação de inspeção voltada a FPSOs do tipo monohull.",
            "No contexto de perigos que podem levar a perda de contenção e, subsequentemente, a major accident hazard."
          ],
          "limites": [
            "A fonte lista perigos, mas não detalha critérios operacionais de prevenção, autorização ou execução de içamentos.",
            "Não fornece limites de vento, mar, visibilidade ou movimentos relativos para iniciar, suspender ou abortar operações."
          ]
        },
        {
          "proposicao": "A orientação associa o desempenho do FPSO durante carregamento e descarregamento a tensões no casco e movimento da embarcação induzidos por clima e equipamentos, indicando que condições ambientais e movimento da unidade interferem no cenário de risco.",
          "trechos": [
            "E5b0085ef8c7f4911:0:699"
          ],
          "condicoes": [
            "No contexto de carregamento e descarregamento de hidrocarbonetos em FPSO."
          ],
          "limites": [
            "A fonte trata de perigos de perda de contenção, não de procedimento de movimentação de cargas entre FPSO e embarcação de apoio.",
            "Não traduz esses fatores em janelas operacionais numéricas nem em regras de blind lift, obstáculos ou SIMOPS."
          ]
        },
        {
          "proposicao": "O escopo declarado da orientação vai da válvula subsea de isolamento até o ponto de conexão de offloading com a instalação a jusante, e explicita que não cobre todos os procedimentos operacionais do FPSO.",
          "trechos": [
            "E5b0085ef8c7f4911:699:1397"
          ],
          "condicoes": [
            "No contexto de delimitação do guia de inspeção."
          ],
          "limites": [
            "A própria fonte restringe sua aplicabilidade e remete questões marítimas a outro guia.",
            "Por isso, não basta para explicar sozinho planejamento detalhado de içamento, gestão de obstáculos, visibilidade limitada ou contingências de carga."
          ]
        }
      ]
    },
    {
      "id": "E506ead24b29cbf4b",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A capacidade ótima de armazenamento de um FPSO é apresentada como específica do local e dependente, entre outros fatores, da frequência de offloading, da janela meteorológica disponível e da duração de interrupções por tempo.",
          "trechos": [
            "E506ead24b29cbf4b:1397:2095"
          ],
          "condicoes": [
            "No contexto de definição de capacidade de armazenamento e operação de FPSO."
          ],
          "limites": [
            "A fonte não converte a influência da janela meteorológica em limites operacionais numéricos.",
            "O trecho trata de armazenamento e offloading de óleo, não de içamento rotineiro de cargas por guindaste."
          ]
        },
        {
          "proposicao": "Entre os principais perigos potenciais de perda de contenção em FPSO, a orientação inclui vazamentos em operações de offloading, inclusive ship to ship, colisão de amarração e falha de mangote, mostrando que interfaces operacionais simultâneas com outra embarcação integram o cenário de risco.",
          "trechos": [
            "E506ead24b29cbf4b:1397:2095",
            "E506ead24b29cbf4b:2095:2316"
          ],
          "condicoes": [
            "No contexto de offloading de hidrocarbonetos em FPSO."
          ],
          "limites": [
            "A fonte não usa o termo SIMOPS nem detalha matriz de interferências entre offloading e movimentação de cargas.",
            "Não estabelece critérios de compatibilidade entre atividades concorrentes."
          ]
        },
        {
          "proposicao": "Cargas derrubadas sobre o convés de processo são listadas como perigo potencial relevante na orientação de inspeção para FPSO.",
          "trechos": [
            "E506ead24b29cbf4b:2095:2316"
          ],
          "condicoes": [
            "No contexto da lista de perigos potenciais de perda de contenção."
          ],
          "limites": [
            "A menção é classificatória e não explica causas imediatas, barreiras, zonas de exclusão ou resposta contingencial.",
            "Não traz critérios sobre visibilidade limitada, blind lift ou proximidade de obstáculos."
          ]
        }
      ]
    },
    {
      "id": "E9dda6573bb343d2b",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "O trabalho apresenta um algoritmo não linear para simulação, no domínio do tempo, do movimento de embarcação na presença de ondas com atenção à representação de não linearidades associadas à inércia, parte submersa, forças externas dependentes do movimento e efeitos do sistema de amarração.",
          "trechos": [
            "E9dda6573bb343d2b:698:1390"
          ],
          "condicoes": [
            "No contexto de modelagem numérica de movimento de embarcação.",
            "Aplicado a uma embarcação tipo FPSO."
          ],
          "limites": [
            "É um estudo de modelagem e validação, não um procedimento operacional para içamento em FPSO.",
            "Não apresenta limites de vento, onda, visibilidade ou critérios de parada para operações com carga."
          ]
        },
        {
          "proposicao": "Segundo o resumo do estudo, as capacidades não lineares do algoritmo permitem representar movimentos de deriva e instabilidades dinâmicas da embarcação.",
          "trechos": [
            "E9dda6573bb343d2b:0:698",
            "E9dda6573bb343d2b:698:1390"
          ],
          "condicoes": [
            "No contexto de simulações de movimento em ondas."
          ],
          "limites": [
            "A fonte não relaciona essas grandezas a envelopes operacionais para transferência de carga entre FPSO e embarcação de apoio.",
            "Não discute obstáculos, blind lifts, SIMOPS ou contingências de içamento."
          ]
        },
        {
          "proposicao": "A validação relatada compara simulações numéricas e testes experimentais com um FPSO ancorado sob ondas de través e de proa, com indicação de boa concordância geral.",
          "trechos": [
            "E9dda6573bb343d2b:0:698",
            "E9dda6573bb343d2b:1390:2087"
          ],
          "condicoes": [
            "Resultado limitado às condições de validação descritas pelo estudo."
          ],
          "limites": [
            "Boa concordância geral no estudo não equivale a validade universal para qualquer mar, configuração de amarração ou operação offshore.",
            "A fonte não estende o resultado a segurança operacional de guindastes ou transferência de cargas."
          ]
        }
      ]
    },
